        int a = Integer.parseInt(t[0]);
        int b = Integer.parseInt(t[1]);
        System.out.println(gcd(a, b));
    }

    public static int  gcd(int x, int y){
        int r;
        if(x < y){
            int temp;
            temp = x;
            x = y;
            y = temp;
        }

        while(y > 0){
            r = x % y;
            x = y;
            y = r;
        }
        return x;
    }

}

