            if(brokes[i]){
                continue;
            }else if(i == 1){
                dp[i] = dp[i-1]%mod;
            }else{
                dp[i] = dp[i-2]%mod + dp[i-1]%mod;
                dp[i] %= mod;
            }
        }
        System.out.println(dp[n]%mod);
    }
}

